from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
N = partial(mk, "neurocognitive", "neurocognitive", "lamp")
DSM_N = DSM("Neurocognitive Disorders")
WHO_DEM = src("src-who-dementia", "Dementia fact sheet", "World Health Organization", "https://www.who.int/news-room/fact-sheets/detail/dementia", seen=True, note="Figures (55 million, ~10 million new cases a year) seen via secondary summaries of the WHO fact sheet.")
NICE97 = src("src-nice-ng97", "Dementia: assessment, management and support for people living with dementia and their carers (NG97)", "NICE", "https://www.nice.org.uk/guidance/ng97", 2018, seen=True)
NIA = src("src-nia-dementia", "What Is Dementia? Symptoms, Types, and Diagnosis", "National Institute on Aging (US)", "https://www.nia.nih.gov/health/alzheimers-and-dementia/what-dementia-symptoms-types-and-diagnosis", note="Not opened.")
ALZ = src("src-alz", "Alzheimer's Association 24/7 Helpline and ALZConnected", "Alzheimer's Association (US)", "https://www.alz.org/helpline", seen=True)
N_COMMS = ["alzheimers-association-helpline-alzconnected", "sane-forums-australia"]

CARDS.append(N("major-and-mild-neurocognitive-disorder", "Major and Mild Neurocognitive Disorder (explainer)", "What 'dementia' and 'neurocognitive disorder' mean", ["dementia", "mild cognitive impairment (MCI)", "NCD"], "F02.8x / F02.A–C (major); G31.84 (mild); varies by cause",
 "A decline in memory, thinking, or other abilities caused by a brain condition. 'Major' is what most people call dementia.",
 "Neurocognitive disorder is the DSM's term for a decline in thinking abilities, such as memory, attention, language, or judgment, caused by a brain condition. 'Mild' means the person still manages daily life independently, often called mild cognitive impairment. 'Major' means the decline interferes with independence, which is what most people call dementia. The cause (Alzheimer's, vascular, and others) is added to the diagnosis; each has its own card. It isn't normal ageing, and much can be done.",
 ["Mum started losing words, then the way home. Getting a name for it, and a plan, was a relief as much as a grief.", "Mild cognitive impairment: scary words, but my dad has stayed stable for four years with the right support.", "The dementia café was the first place we laughed again."],
 ["Decline in memory, attention, language, judgment, or recognizing things, from a previous level", "Noticed by the person, by family, or on testing", "Mild: still independent in daily life, with effort or workarounds", "Major: needs help with everyday tasks like money, medication, or cooking", "Not caused by delirium or another mental disorder", "A cause is identified where possible: Alzheimer's, vascular, Lewy body, and others"],
 [{"myth": "Dementia is a normal part of getting old.", "fact": "Most older people never develop dementia. It's caused by disease, and age is a risk factor, not a cause."},
  {"myth": "Mild cognitive impairment always turns into dementia.", "fact": "Some people with MCI progress, some stay stable, and some improve, especially when a treatable cause like depression, medication, or sleep apnoea is found."},
  {"myth": "Nothing can be done, so why bother with a diagnosis.", "fact": "Diagnosis opens the door to treatments that help symptoms, planning while the person can decide, support for carers, and research. Some causes are reversible."}],
 {"plain": "More than 55 million people worldwide live with dementia, with around 10 million new cases a year. Most live in low- and middle-income countries.", "figure": "55 million people with dementia worldwide; nearly 10 million new cases each year; Alzheimer's disease accounts for 60–70% (WHO)", "source_ref": "src-who-dementia"},
 {"plain_summary": "Assessment finds the cause and rules out reversible ones (thyroid problems, vitamin deficiency, depression, medication side effects). For Alzheimer's and some other dementias, medications prescribed and monitored by a doctor can ease symptoms for a time. Cognitive stimulation therapy, staying physically and socially active, treating hearing and vision loss, and managing heart health all help. Support for carers is part of treatment. Planning for the future while the person can take part is strongly recommended.",
  "evidence_based_options": ["Full assessment including reversible causes", "Medication for Alzheimer's and some other dementias, prescribed and monitored by a doctor", "Cognitive stimulation therapy and structured activity", "Carer education and support; advance care planning"],
  "self_help_that_supports_care": ["Keeping physically active, socially connected, and mentally engaged", "Treating hearing loss, which protects thinking", "Routines, labels, lists, and a calm home", "Carers: joining a support group early, not when exhausted"],
  "guideline_refs": ["src-nice-ng97"]},
 "If you or someone close to you is having memory or thinking problems that are new, getting worse, or affecting daily life, see a doctor for an assessment. Earlier is better, for treatment, support, and planning.",
 "Occasional forgetfulness, slower recall with age, and the brain fog of stress, depression, or poor sleep aren't neurocognitive disorder. Delirium is a sudden, fluctuating confusion with a medical cause. Lifelong learning difficulties are intellectual disability, not dementia.",
 "A diagnosis is the start of getting help, not the end of a life. People live well with dementia for years, especially with support, and carers don't have to do it alone.",
 ["alzheimers-disease-neurocognitive-disorder", "vascular-neurocognitive-disorder", "lewy-body-neurocognitive-disorder", "frontotemporal-neurocognitive-disorder", "parkinsons-disease-neurocognitive-disorder", "delirium", "major-depressive-disorder"],
 ["dementia", "mild-cognitive-impairment", "cognition", "confabulation", "sundowning", "guardianship", "carer-rights"],
 N_COMMS, ("Soft line illustration of an older person and a younger relative doing a jigsaw together at a kitchen table, a labelled cupboard behind them, warm light. Pastel amber and cream.", "An older person and a younger relative do a jigsaw together at a kitchen table."),
 [DSM_N, WHO_DEM, NICE97, NIA, ALZ], qs=["Confirm WHO figures on the fact sheet.", "Add Alzheimer's Society (UK) and Dementia Australia after verifying their helplines."],
 cult="Dementia carries heavy stigma in many cultures and is often seen as madness or fate. Family care is the norm in most of the world, and services that work with families, in their language, reach more people. Diagnosis rates are far lower in low-income countries.",
 subs=[{"title": "How it's coded", "text": "Major NCD is coded by cause (for example G30.9 for Alzheimer's) plus F02.8x or the severity codes F02.A–C, with or without behavioural or psychological symptoms. Mild NCD is G31.84."},
       {"title": "Behavioural and psychological symptoms", "text": "Agitation, anxiety, depression, hallucinations, and sleep changes are common in dementia and have their own approaches, with medication used cautiously."}], sens="standard", card_type="explainer"))

def ncd(tid, name, title, aka, code, one, simple, feel, signs, myths, how, helps, reach, isnot, hope, related, gloss, comms, vis, srcs, qs=[], subs=None, cult=None, young=None, notes=[]):
    return N(tid, name, title, aka, code, one, simple, feel, signs, myths, how, helps, reach, isnot, hope, related, gloss, comms, vis, srcs, qs=qs, subs=subs, cult=cult, young=young, sens="standard", notes=notes, clin=False)

CARDS.append(ncd("alzheimers-disease-neurocognitive-disorder", "Neurocognitive Disorder Due to Alzheimer's Disease", "The most common cause of dementia", ["Alzheimer's disease", "Alzheimer's dementia"], "G30.9 + F02.8x (major); G31.84 (mild)",
 "A gradual, progressive decline in memory and thinking caused by Alzheimer's disease, the commonest cause of dementia.",
 "Alzheimer's disease is a brain condition that slowly damages nerve cells, usually starting with short-term memory: forgetting recent conversations, repeating questions, misplacing things. Over years it spreads to language, finding the way, planning, and recognizing people. It's the cause of most dementia and mainly affects people over 65, though it can start earlier. There's no cure yet, but medications can ease symptoms, newer treatments can slow early disease for some, and support makes an enormous difference.",
 ["Dad asks the same question five times and each time it's new to him. I've learned to answer each time as if it is.", "I was diagnosed at 58. I'm still here, still me, doing what I can while I can.", "The support group taught me how to be with my wife now, not just grieve who she was."],
 ["Forgetting recent events and conversations; repeating questions", "Trouble finding words, following conversations, or managing money", "Getting lost in familiar places", "Difficulty with planning, judgment, and everyday tasks", "Changes in mood, personality, or withdrawal", "Gradual onset and slow, steady worsening over years"],
 [{"myth": "Alzheimer's and dementia are the same thing.", "fact": "Dementia is the umbrella; Alzheimer's is the most common cause of it. Other causes have different patterns and treatments."},
  {"myth": "If a parent had it, I'll get it.", "fact": "Most Alzheimer's isn't directly inherited. Family history raises risk somewhat; healthy heart, hearing, activity, and social life lower it."},
  {"myth": "Nothing can be done.", "fact": "Medication, newer disease-modifying treatments for some people, activity, support, and planning all change the course and quality of life."}],
 {"plain": "Alzheimer's disease causes around 6 to 7 in every 10 cases of dementia worldwide, affecting tens of millions of people, and risk rises sharply after 65.", "figure": "60–70% of the 55 million people with dementia worldwide (WHO)", "source_ref": "src-who-dementia"},
 {"plain_summary": "Cholinesterase inhibitors and memantine, prescribed and monitored by a doctor, can modestly ease symptoms. Newer antibody treatments that slow early Alzheimer's are approved in some countries for carefully selected people, with significant monitoring. Cognitive stimulation therapy, exercise, social activity, and treating hearing loss help. Behavioural and psychological symptoms are managed with non-drug approaches first. Carer support, dementia-friendly adjustments at home, and early planning are central.",
  "evidence_based_options": ["Cholinesterase inhibitors and memantine, prescribed and monitored by a doctor", "Disease-modifying antibody treatments for selected people with early disease, where approved", "Cognitive stimulation therapy, exercise, and social engagement", "Carer education, support groups, and advance care planning"],
  "self_help_that_supports_care": ["Routines, labels, and reminders at home", "Staying active, social, and engaged in enjoyable activities", "Carers: respite, support groups, and looking after their own health", "Planning finances, care wishes, and legal arrangements early"],
  "guideline_refs": ["src-nice-ng97"]},
 "If memory problems are getting worse and affecting daily life, see a doctor for assessment. Early diagnosis gives access to treatment, support, and the chance to plan. Carers: ask for help before you're exhausted.",
 "Normal age-related forgetfulness, memory problems from depression, medication, thyroid or vitamin problems, and other dementias are not Alzheimer's. Only assessment can tell.",
 "People live meaningful lives with Alzheimer's for years, and families find connection in new ways. Nobody has to face it alone.",
 ["major-and-mild-neurocognitive-disorder", "vascular-neurocognitive-disorder", "lewy-body-neurocognitive-disorder", "delirium", "major-depressive-disorder"],
 ["dementia", "mild-cognitive-impairment", "sundowning", "anosognosia", "anticipatory-grief", "carer-rights"],
 N_COMMS, ("Soft line illustration of an older person and a grandchild looking through a photo album together on a sunny sofa, a dog at their feet. Pastel amber and sky blue.", "An older person and a grandchild look through a photo album together on a sunny sofa."),
 [DSM_N, WHO_DEM, NICE97, ALZ, NIA], qs=["Add verified Alzheimer's Society (UK) and Dementia Australia entries."],
 cult="Alzheimer's affects every community. Diagnosis comes later for people from minority and lower-income groups, and some languages have no word for dementia. Culturally adapted services and interpreters improve care.",
 young="Early-onset Alzheimer's (before 65) is rare but real and often misdiagnosed as stress or depression. Younger people need services designed for their stage of life, including work and family responsibilities."))

CARDS.append(ncd("vascular-neurocognitive-disorder", "Vascular Neurocognitive Disorder", "Dementia caused by problems with blood flow to the brain", ["vascular dementia", "multi-infarct dementia", "post-stroke dementia"], "F01.5x / F01.A–C (major); G31.84 (mild)",
 "A decline in thinking caused by damage to the brain's blood supply, from strokes or disease of small blood vessels.",
 "Vascular neurocognitive disorder happens when reduced blood flow damages brain tissue, through strokes, mini-strokes, or disease of the small vessels deep in the brain. Thinking problems often involve slowed thinking, trouble planning and organizing, and difficulty with attention, sometimes more than memory. It may start suddenly after a stroke or build gradually, often in steps. It's the second most common cause of dementia and shares risk factors with heart disease, so managing blood pressure, diabetes, and smoking matters.",
 ["After the stroke, Mum's memory was okay but she couldn't plan a meal any more. The neurologist explained it was vascular.", "He's had three small strokes. Each one took something. Keeping his blood pressure down is the fight now.", "The stroke support group understands this version of dementia better than anyone."],
 ["Slowed thinking, trouble planning, organizing, or concentrating", "Memory problems, often less prominent than in Alzheimer's", "Onset after a stroke, or gradual, stepwise worsening", "Walking difficulties, unsteadiness, or bladder problems", "Mood changes, apathy, or emotional swings", "History of strokes, high blood pressure, diabetes, or heart disease"],
 [{"myth": "It's just Alzheimer's by another name.", "fact": "The cause and pattern differ, and vascular dementia often progresses in steps. Many people have both, called mixed dementia."},
  {"myth": "Once it starts, nothing slows it.", "fact": "Controlling blood pressure, diabetes, cholesterol, and smoking, and preventing further strokes, can slow or stall progression."},
  {"myth": "Memory loss is the main sign.", "fact": "Slowed thinking and trouble planning are often the first and biggest problems."}],
 {"plain": "Vascular disease causes or contributes to around 1 in 5 cases of dementia, and it commonly occurs together with Alzheimer's changes.", "figure": "Estimated 15–20% of dementia cases, with mixed pathology common (DSM-5-TR text and reviews)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "The main treatment is preventing further damage: controlling blood pressure, diabetes, and cholesterol, stopping smoking, and medication to prevent further strokes, all prescribed and monitored by a doctor. Alzheimer's medications are sometimes used in mixed dementia. Rehabilitation, cognitive stimulation, exercise, and support for mood help. Carer support and planning are as important as in any dementia.",
  "evidence_based_options": ["Treatment of vascular risk factors and stroke prevention, prescribed and monitored by a doctor", "Rehabilitation after stroke, including occupational and physiotherapy", "Cognitive stimulation and physical activity", "Treatment of depression and apathy; carer support"],
  "self_help_that_supports_care": ["Taking blood pressure and other medications consistently", "Regular walking or other exercise as able", "A heart-healthy diet and no smoking", "Stroke and dementia support groups for the person and carers"],
  "guideline_refs": ["src-nice-ng97"]},
 "If thinking has changed after a stroke, or someone with heart disease or diabetes is becoming slower and more muddled, see a doctor. Sudden confusion, weakness, or speech problems are emergency signs of stroke: call emergency services.",
 "A single stroke that affects one function, like speech, without broader decline isn't vascular dementia. Delirium during illness is different. Alzheimer's has a different pattern, though the two often overlap.",
 "Vascular dementia is the one form where lifestyle and medical care can genuinely slow things down. Every stroke prevented is thinking preserved.",
 ["major-and-mild-neurocognitive-disorder", "alzheimers-disease-neurocognitive-disorder", "major-depressive-disorder", "delirium"],
 ["dementia", "cognition", "executive-function", "carer-rights"],
 N_COMMS, ("Soft line illustration of an older person taking a brisk walk with a friend, blood-pressure monitor at home visible through a window, autumn trees. Pastel amber and green.", "An older person walks briskly with a friend under autumn trees."),
 [DSM_N, NICE97, NIA], qs=["Find a primary prevalence source.", "Add stroke association communities (Stroke Association UK, American Stroke Association) after verification."]))

CARDS.append(ncd("lewy-body-neurocognitive-disorder", "Neurocognitive Disorder With Lewy Bodies", "Dementia with vivid hallucinations and changing alertness", ["Lewy body dementia", "dementia with Lewy bodies", "DLB"], "G31.83 + F02.8x (major); G31.84 (mild)",
 "A dementia with attention that comes and goes, vivid visual hallucinations, and Parkinson's-like movement problems.",
 "Dementia with Lewy bodies is caused by protein deposits (Lewy bodies) in brain cells. Its signature features are attention and alertness that swing from hour to hour or day to day, vivid and detailed visual hallucinations (often people or animals), Parkinson's-like stiffness and slowness, and acting out dreams in sleep. Memory may be less affected early on. It's the third most common dementia and often misdiagnosed. Some antipsychotic medicines can be dangerous in this condition, so an accurate diagnosis matters.",
 ["Dad sees children in the garden who aren't there. He's not frightened by them. We've learned not to argue.", "One day she's sharp, the next she can't follow a sentence. The swings were the clue.", "The wrong medication nearly killed him. Finding a specialist who knew Lewy body was everything."],
 ["Attention and alertness that fluctuate markedly, like switching on and off", "Seeing detailed things that aren't there, often people or animals", "Stiffness, slowness, shuffling walk, or tremor, like Parkinson's", "Acting out dreams, sometimes years before other symptoms", "Falls, fainting, or blood-pressure drops", "Bad reactions to some antipsychotic medicines"],
 [{"myth": "Hallucinations in an older person mean psychosis or Alzheimer's.", "fact": "Vivid visual hallucinations with fluctuating alertness are a hallmark of Lewy body dementia, which needs different care."},
  {"myth": "Any dementia can be treated the same way.", "fact": "People with Lewy body dementia can react severely to certain antipsychotics. Getting the diagnosis right is a safety issue."},
  {"myth": "It's the same as Parkinson's disease dementia.", "fact": "They're closely related and share Lewy bodies. The main difference is timing: in DLB, thinking changes come first or within a year of movement symptoms."}],
 {"plain": "Lewy body dementia is about 1 in 20 to 1 in 10 of all dementia cases. It is often missed.", "figure": "Estimated 5%–10% of dementia cases; higher in autopsy studies (DSM-5-TR text and reviews)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Dementia medicines (cholinesterase inhibitors), prescribed and monitored by a doctor, often help thinking and hallucinations, sometimes more than in Alzheimer's. Movement problems may be treated carefully with Parkinson's medicines. Antipsychotics are avoided where possible and used only with great care. Good lighting, calm responses to hallucinations, treating sleep problems, and physio to prevent falls all help. A specialist check is strongly advised.",
  "evidence_based_options": ["Cholinesterase inhibitors, prescribed and monitored by a doctor", "Cautious treatment of movement symptoms; avoiding most antipsychotics", "Treatment of REM sleep behaviour disorder and blood-pressure problems", "Physiotherapy, falls prevention, and carer education"],
  "self_help_that_supports_care": ["Not arguing with hallucinations; reassurance and calm", "Good lighting and reducing shadows at home", "Telling every clinician 'Lewy body: antipsychotic-sensitive'", "Lewy body-specific carer groups, which understand the swings"],
  "guideline_refs": ["src-nice-ng97"]},
 "Does someone see vivid things that aren't there, swing in alertness from day to day, move like a person with Parkinson's, or act out dreams? Ask for a specialist memory or neurology check. Say the words 'Lewy body dementia'.",
 "Hallucinations from delirium, medication, or eye disease aren't Lewy body dementia. Parkinson's disease dementia has the same brain changes, but movement problems come first by a year or more.",
 "With the right diagnosis and the right medicines, hallucinations often ease and thinking steadies. Carer groups make the ups and downs easier to bear.",
 ["major-and-mild-neurocognitive-disorder", "parkinsons-disease-neurocognitive-disorder", "alzheimers-disease-neurocognitive-disorder", "parasomnias", "delirium", "understanding-psychosis"],
 ["dementia", "hallucination", "antipsychotic", "carer-rights"],
 N_COMMS + ["lewy-body-society-uk", "lbda-caregiver-link"], ("Soft line illustration of an older person sitting in a well-lit living room with a carer, lamps on, a calendar clock on the wall, a cat on the rug. Pastel amber and lavender.", "An older person sits with a carer in a brightly lit living room with a calendar clock on the wall."),
 [DSM_N, NICE97, src("src-lbs", "The Lewy Body Society (UK) helpline", "Lewy Body Society / Dementia UK", "https://www.lewybody.org/", seen=True, note="Helpline 0800 888 6678 seen in an Alzheimer's Society resource listing."), src("src-lbda", "Lewy Body Dementia Association", "LBDA (US)", "https://www.lbda.org/", note="Not opened; Caregiver Link 800-539-9767 seen via a third-party listing.")],
 qs=["Find a primary prevalence source.", "Confirm LBDA helpline details on lbda.org."]))

CARDS.append(ncd("frontotemporal-neurocognitive-disorder", "Frontotemporal Neurocognitive Disorder", "A dementia that changes personality or language first", ["frontotemporal dementia", "FTD", "Pick's disease (one form)", "primary progressive aphasia"], "G31.09 + F02.8x (major); G31.84 (mild)",
 "A dementia that starts in the front and sides of the brain and changes behaviour, personality, or speech before memory.",
 "Frontotemporal dementia damages the front and side parts of the brain. Those parts handle behaviour, judgment, empathy, and language. Unlike Alzheimer's, it usually starts between 45 and 65, and memory is often fine early on. In the behaviour form, a person may act rudely, on impulse, or without feeling. Families often mistake this for depression. In the language forms, speech or understanding slowly breaks down. It's often missed for years. Support and planning help a lot.",
 ["My husband started making crude jokes at work and spending our savings. We thought it was a breakdown. It was FTD.", "She lost the word for 'fork', then 'daughter'. Her memory of us was fine. That's what made it so cruel.", "The AFTD group was the first place anyone had heard of it."],
 ["Changes in personality or judgment: being tactless, acting on impulse, not caring", "Or: progressive difficulty with speech, naming, or understanding words", "Repeating the same actions; changes in eating", "Memory relatively preserved in the early stages", "Usual onset between 45 and 65, often misdiagnosed as psychiatric illness", "Lack of insight into the changes"],
 [{"myth": "Dementia always starts with memory loss.", "fact": "FTD often starts with behaviour or language changes while memory stays intact, which is why it's missed."},
  {"myth": "The person is being deliberately rude or selfish.", "fact": "The disease damages the brain regions that control social behaviour and empathy. The person usually can't see the change."},
  {"myth": "It's a rare condition that only affects the very old.", "fact": "FTD is one of the commonest dementias in people under 65."}],
 {"plain": "FTD is uncommon overall. But among people under 65 it is one of the most common dementias, making up perhaps 1 in 10 to 1 in 5 cases.", "figure": "Estimated 2–10 per 100,000 in the general population; roughly 10–20% of dementia under 65 (reviews)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "No medicine slows FTD yet, and Alzheimer's drugs don't help. Care focuses on structure, routine, and a calm setting to manage behaviour. Speech therapy helps the language forms. Occupational therapy helps with daily life. Sometimes medication is used for agitation or compulsions, prescribed and monitored by a doctor. Because it often starts in working life, help with jobs, money, family, and early legal planning is vital. Carers need support. FTD is especially hard on families.",
  "evidence_based_options": ["Specialist diagnosis, including genetic counselling where relevant", "Behavioural and environmental strategies; structure and routine", "Speech and language therapy for language variants", "Medication for specific symptoms where needed, prescribed and monitored by a doctor; carer support"],
  "self_help_that_supports_care": ["Simplifying choices and keeping routines", "Protecting finances early, with legal advice", "Not taking personality changes personally, however hard", "FTD-specific carer groups, which understand behaviour others don't"],
  "guideline_refs": ["src-nice-ng97"]},
 "Has someone in midlife changed in personality, behaviour, or speech in ways that aren't like them, and they don't seem to notice? Ask for a neurology or memory clinic referral. Say the words 'frontotemporal dementia'.",
 "Depression, bipolar disorder, psychosis starting late in life, and Alzheimer's can look similar. Careful assessment tells them apart. If the person fully sees the change in themselves, FTD is unlikely.",
 "Families facing FTD find strength in each other. Specialist support turns an isolating, misunderstood illness into one that can be faced together.",
 ["major-and-mild-neurocognitive-disorder", "alzheimers-disease-neurocognitive-disorder", "major-depressive-disorder", "bipolar-i-disorder", "communication-disorders"],
 ["dementia", "aphasia", "executive-function", "anosognosia", "carer-rights"],
 N_COMMS + ["aftd-helpline-and-groups"], ("Soft line illustration of a middle-aged person and their partner gardening together with a simple picture-labelled task list on a post, a neighbour waving. Pastel amber and green.", "A middle-aged couple garden together beside a picture-labelled task list on a post."),
 [DSM_N, NICE97, src("src-aftd", "AFTD HelpLine and support groups", "Association for Frontotemporal Degeneration (US)", "https://www.theaftd.org/", seen=True, note="HelpLine 1-866-507-7222 seen on AFTD pages.")],
 qs=["Find a primary prevalence source.", "Add Rare Dementia Support (UK) after verification."],
 subs=[{"title": "Variants", "text": "Behavioural variant (changes in conduct and personality) and language variants (primary progressive aphasia: semantic, non-fluent, and logopenic types). Some people also develop motor neurone disease or movement disorders."}]))

CARDS.append(ncd("parkinsons-disease-neurocognitive-disorder", "Neurocognitive Disorder Due to Parkinson's Disease", "Thinking changes that come with Parkinson's", ["Parkinson's disease dementia", "PDD", "mild cognitive impairment in Parkinson's"], "G20.x + F02.8x (major); G31.84 (mild)",
 "A decline in thinking that develops in a person who has had Parkinson's disease for a year or more.",
 "Parkinson's disease is best known for shaking, stiffness, and slowness. But over time it also affects thinking in many people. Mild changes are common: slower thinking, trouble doing two things at once, and hunting for words. Some people develop dementia, usually years into the illness. That brings trouble with attention, planning, and judging what they see, and sometimes hallucinations. It shares its brain changes with Lewy body dementia. Good care balances movement medicines with clear thinking.",
 ["Fifteen years of Parkinson's, and the slowness crept from his body into his thinking. The nurse specialist saw it before we did.", "I can't do two things at once any more. One at a time, and I'm still me.", "The Parkinson's helpline knew exactly what questions to ask about the hallucinations."],
 ["Established Parkinson's disease for at least a year before thinking changes", "Slowed thinking, trouble with attention, planning, and multitasking", "Difficulty with visual judgment and finding the way", "Memory problems, mainly with retrieval", "Seeing things that aren't there, loss of drive, anxiety, or depression", "Alertness that comes and goes; sleepiness in the day"],
 [{"myth": "Parkinson's only affects movement.", "fact": "Thinking, mood, sleep, and bodily functions are all affected by Parkinson's. Cognitive change is common, especially later."},
  {"myth": "Everyone with Parkinson's gets dementia.", "fact": "Many do over the long term, but many don't, and mild changes don't always progress."},
  {"myth": "Confusion means the Parkinson's medicines should be stopped.", "fact": "Medicines need careful balancing, not stopping. A specialist can adjust them to protect both movement and thinking."}],
 {"plain": "About 1 in 4 people with Parkinson's have mild thinking changes when diagnosed. Most develop dementia after many years with the disease.", "figure": "Mild NCD in about 27% of people with Parkinson's; dementia in up to 75% after 10 or more years (DSM-5-TR text and reviews)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Dementia medicines (cholinesterase inhibitors), prescribed and monitored by a doctor, help thinking and hallucinations in Parkinson's dementia. Parkinson's medicines are adjusted to balance movement with clear thinking. Antipsychotics are avoided or used very carefully, as in Lewy body dementia. Treating depression, sleep problems, and loss of drive helps. Occupational therapy, exercise, and memory tricks support daily life. Parkinson's nurses and charities are a huge help.",
  "evidence_based_options": ["Cholinesterase inhibitors, prescribed and monitored by a doctor", "Careful adjustment of Parkinson's medication by a specialist", "Treatment of depression, sleep, and hallucinations with Parkinson's-safe approaches", "Exercise, occupational therapy, and carer support"],
  "self_help_that_supports_care": ["One task at a time; written lists and routines", "Exercise, which helps both movement and thinking", "Reporting hallucinations or confusion early to the Parkinson's team", "Parkinson's support groups and helplines for the person and family"],
  "guideline_refs": ["src-nice-ng71"]},
 "If someone with Parkinson's is getting confused, slower in thinking, or seeing things, tell the Parkinson's team or doctor. Changes to medicines and other treatments can help. Sudden confusion may be an infection or a medicine problem and needs a prompt check.",
 "Slowness of movement and speech in Parkinson's can look like cognitive decline without being it. Depression and medication side effects cause similar changes. Lewy body dementia is diagnosed when thinking problems come first.",
 "Thinking changes in Parkinson's can be managed. With the right support, people go on enjoying their relationships, hobbies, and purpose.",
 ["major-and-mild-neurocognitive-disorder", "lewy-body-neurocognitive-disorder", "major-depressive-disorder", "parasomnias", "delirium"],
 ["dementia", "mild-cognitive-impairment", "hallucination", "carer-rights"],
 N_COMMS + ["parkinsons-foundation-helpline", "parkinsons-uk-helpline"], ("Soft line illustration of an older person at a seated exercise class with others, a Parkinson's nurse leading, bright community hall. Pastel amber and teal.", "An older person joins a seated exercise class led by a nurse in a bright community hall."),
 [DSM_N, src("src-nice-ng71", "Parkinson's disease in adults (NG71)", "NICE", "https://www.nice.org.uk/guidance/ng71", 2017, note="Not opened."), src("src-pf", "Parkinson's Foundation Helpline", "Parkinson's Foundation (US)", "https://www.parkinson.org/resources-support/helpline", seen=True), src("src-puk", "Parkinson's UK helpline", "Parkinson's UK", "https://www.parkinsons.org.uk/", note="Helpline 0808 800 0303 seen in a listing; site not opened.")],
 qs=["Find a primary prevalence source."]))

CARDS.append(ncd("huntingtons-disease-neurocognitive-disorder", "Neurocognitive Disorder Due to Huntington's Disease", "Thinking and mood changes in an inherited brain condition", ["Huntington's disease", "HD", "Huntington's chorea (older term)"], "G10 + F02.8x (major); G31.84 (mild)",
 "Thinking and mood changes caused by Huntington's disease, a condition passed down in families that also affects movement.",
 "Huntington's disease is a rare condition caused by a single gene. Each child of a parent with it has a 50% chance of inheriting it. It usually starts between 30 and 50 and gets worse over 15 to 20 years. It affects movement (jerky movements, clumsiness), thinking (planning, slower thought), and mood (depression, short temper, not caring). Thinking and mood changes often come before movement problems. There's no cure, but symptoms can be treated and families supported.",
 ["I watched it take my mother. Then I had the test. Knowing changed how I live, not whether I live.", "The irritability came years before the movements. We blamed stress.", "HDSA connected us with families who'd walked this road. That mattered more than any drug."],
 ["Huntington's in the family; a positive gene test", "Slowed thinking, trouble planning, organizing, and switching tasks", "Depression, short temper, not caring, anxiety, or stuck thoughts", "Jerky movements you can't control, clumsiness, or restlessness", "Onset usually between 30 and 50; gradual progression", "Thinking and mood changes often preceding movement symptoms"],
 [{"myth": "Huntington's is only a movement disorder.", "fact": "Thinking and mood changes are core features and often appear first. Depression and suicide risk are serious concerns."},
  {"myth": "If I have the gene, there's no point planning anything.", "fact": "Many people live decades after diagnosis. Planning, treatment, and support shape those years, and research is advancing."},
  {"myth": "Everyone at risk should get tested.", "fact": "Testing is a personal choice made with genetic counselling. Many at-risk people choose not to test, and that's valid."}],
 {"plain": "Huntington's disease is rare. It affects about 5 to 10 people in every 100,000 among people of European descent, and fewer elsewhere.", "figure": "About 5–10 per 100,000 in European-origin populations; lower in Asian and African populations (reviews)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Care comes from a team: nerve doctors, psychiatrists, therapists, dietitians, and social workers. Medicines, prescribed and monitored by a doctor, can ease the jerky movements, depression, short temper, and other symptoms. Physio, speech therapy, occupational therapy, and good nutrition keep people doing more for longer. Genetic counselling supports families and relatives at risk. Specialist clinics and charities know this disease well. Planning care and money early makes a difference.",
  "evidence_based_options": ["Specialist HD clinic and multidisciplinary care", "Medication for movement, mood, and behavioural symptoms, prescribed and monitored by a doctor", "Physiotherapy, speech, occupational therapy, and nutrition support", "Genetic counselling; carer and family support"],
  "self_help_that_supports_care": ["Routines and a calm, predictable environment", "Staying active and eating enough, as HD burns a lot of energy", "Talking about mood changes early; depression is treatable", "HD organizations and groups for the person, carers, and at-risk relatives"],
  "guideline_refs": ["src-hdsa"]},
 "If you have a family history of Huntington's and notice mood, thinking, or movement changes, contact a doctor or HD clinic. For questions about testing, ask for genetic counselling. If you're feeling hopeless or thinking of ending your life, use the crisis strip now; depression in HD is treatable.",
 "Other movement disorders and dementias can look similar. A gene test confirms Huntington's. Depression or anxiety in someone at risk doesn't mean the disease has started.",
 "Families living with Huntington's are among the strongest communities in medicine. Research into treatments that slow the disease is moving faster than ever.",
 ["major-and-mild-neurocognitive-disorder", "major-depressive-disorder", "obsessive-compulsive-disorder", "suicidal-thoughts-and-behavior", "medication-induced-movement-disorders"],
 ["dementia", "executive-function", "carer-rights", "anticipatory-grief", "suicidal-ideation"],
 ["hdsa-helpline-and-groups"] + N_COMMS, ("Soft line illustration of three generations of a family on a porch, one in a wheelchair, all laughing at something on a phone, a genetic counsellor's leaflet on the table. Pastel amber and rose.", "Three generations of a family laugh together on a porch, one in a wheelchair."),
 [DSM_N, src("src-hdsa", "HDSA Helpline and support groups", "Huntington's Disease Society of America", "https://hdsa.org/hdsa-helpline/", seen=True), src("src-hda", "Huntington's Disease Association (UK)", "HDA", "https://www.hda.org.uk/", note="Not opened.")],
 qs=["Find a primary prevalence source.", "Verify HDA (UK) and add."], notes=["Suicide risk is raised in HD; the 'when to reach out' text names this and the crisis strip applies via the chapter rule."]))

CARDS.append(ncd("traumatic-brain-injury-neurocognitive-disorder", "Neurocognitive Disorder Due to Traumatic Brain Injury", "Thinking changes after a head injury", ["TBI", "post-concussion cognitive problems", "brain injury"], "S06.2X9S + F02.8x (major); G31.84 (mild)",
 "Lasting trouble with memory, attention, or thinking after a blow to the head, long after the early recovery.",
 "A brain injury from a fall, crash, assault, sport, or blast can leave lasting changes in thinking. People may think more slowly, lose focus, forget things, and struggle to plan. Mood, temper, energy, and sleep often change too. The diagnosis applies when these last beyond the early weeks. Most mild injuries (concussions) heal within weeks. Severe or repeated injuries can cause lasting problems. Rehab helps. So does knowing that the person has a real injury.",
 ["Six months after the crash I looked fine. I couldn't follow a recipe or a conversation in a noisy room.", "The anger scared me more than the memory problems. Nobody had warned me that was part of it.", "Brain injury rehab was slow and boring and it gave me my job back."],
 ["A head injury with blackout, confusion, memory loss, or nerve signs", "Lasting trouble with attention, memory, thinking speed, or planning", "Fatigue, headaches, sleep problems, sensitivity to noise or light", "Short temper, mood swings, depression, anxiety, or personality change", "Difficulties at work, school, or in relationships", "Problems that go on longer than expected for that injury"],
 [{"myth": "If the scan is clear, the brain is fine.", "fact": "Scans miss much of the damage in brain injury. Symptoms and assessment of thinking matter more than imaging."},
  {"myth": "Concussion is trivial.", "fact": "Most concussions recover, but some don't, and repeated concussions add up. Rest, graded return, and follow-up matter."},
  {"myth": "Personality change after brain injury is the person's choice.", "fact": "Injury to the frontal lobes directly affects impulse control, mood, and judgment. Understanding this helps families cope."}],
 {"plain": "Traumatic brain injuries are very common, with millions of emergency visits a year in the US alone. Most are mild and recover; a minority leave lasting cognitive problems.", "figure": "Over 2 million TBI-related emergency visits a year in the US (CDC); most are mild; persistent NCD follows a minority, more after moderate–severe or repeated injury", "source_ref": "src-dsm", "note": "CDC figure from memory; needs confirmation."},
 {"plain_summary": "Treatment is rehab. Thinking rehab retrains attention and memory and teaches ways around the gaps. Occupational therapy helps with daily tasks and work. Physio helps the body. Talk therapy helps with mood, anger, and adjusting. Medication, prescribed and monitored by a doctor, may be used for depression, sleep, or headaches. Teaching the person and family what to expect is a core part. A step-by-step return to work or study, with adjustments, improves results. Avoiding another injury matters, especially in sport.",
  "evidence_based_options": ["Cognitive rehabilitation and compensatory strategies", "Occupational, physio-, and speech therapy", "Psychological therapy for mood, anger, and adjustment", "Graded return to work or study; medication for specific symptoms, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Pacing: rest before fatigue, not after", "External memory aids: notes, alarms, one notebook", "Quiet environments and one task at a time", "Brain injury peer groups, which understand invisible injury"],
  "guideline_refs": ["src-nice-ng232"]},
 "If thinking, mood, or energy haven't come back to normal weeks after a head injury, ask a doctor about a brain injury check and rehab. Go to emergency care for a worsening headache, vomiting, confusion, a seizure, or sleepiness after any head injury.",
 "Normal recovery from a concussion over a few weeks isn't this disorder. PTSD after the same accident can look similar and is treated differently; both can happen. Dementia from other causes isn't counted unless the injury set it off.",
 "The brain keeps healing for a long time after injury, and rehabilitation keeps building on it. Many people return to full lives, often with new strategies.",
 ["major-and-mild-neurocognitive-disorder", "posttraumatic-stress-disorder", "major-depressive-disorder", "intermittent-explosive-disorder", "crime-disaster-and-legal-problems"],
 ["cognition", "executive-function", "working-memory", "brain-fog", "occupational-therapist"],
 ["headway-uk-helpline"] + N_COMMS, ("Soft line illustration of a person in a quiet rehab room doing a memory exercise with a therapist, a notebook and a timer on the desk, a cycle helmet hanging on a hook. Pastel amber and blue.", "A person does a memory exercise with a therapist in a quiet rehab room, a cycle helmet on a hook."),
 [DSM_N, src("src-nice-ng232", "Head injury: assessment and early management (NG232)", "NICE", "https://www.nice.org.uk/guidance/ng232", 2023, note="Not opened."), src("src-headway", "Headway helpline", "Headway: the brain injury association (UK)", "https://www.headway.org.uk/supporting-you/helpline/", seen=True), src("src-cdc-tbi", "TBI data", "CDC", "https://www.cdc.gov/traumatic-brain-injury/data-research/index.html", note="Not opened.")],
 qs=["Confirm CDC TBI figures and URL.", "Add Brain Injury Association of America and Brain Injury Australia after verification."],
 young="Children's brains are still growing, so the effects of an injury can show up over time, especially in learning and behaviour. Sport concussion rules and school support plans matter."))

CARDS.append(ncd("neurocognitive-disorder-other-causes", "Neurocognitive Disorders Due to Other Causes", "Thinking decline from HIV, alcohol, and other conditions", ["HIV-associated neurocognitive disorder", "alcohol-related dementia", "prion disease (CJD)", "mixed dementia", "unspecified dementia"], "varies",
 "Decline in thinking caused by HIV, prion disease, long-term drug or alcohol use, other illnesses, or several causes at once.",
 "Many conditions beyond the common dementias can cause lasting decline in thinking. HIV can affect the brain, though much less since effective treatment. Long-term heavy alcohol use can cause memory damage, including Korsakoff syndrome, some of which improves with abstinence and vitamin B1. Prion diseases like CJD are rare and rapidly progressive. Multiple sclerosis, brain tumours, infections, and thyroid or vitamin problems can all affect thinking. Finding the cause matters because some are treatable or reversible.",
 ["Years of drinking left my memory in pieces. Thiamine and sobriety gave some of it back.", "Living with HIV since the 90s, I'd noticed my thinking slow. My doctor adjusted treatment and checked everything else.", "Dad's dementia turned out to be partly a vitamin deficiency. Not all of it. But enough to make a difference."],
 ["Decline in memory, attention, or thinking from a previous level", "A known medical cause: HIV, prion disease, MS, infection, tumour, or another condition", "Or long-term heavy substance use, especially alcohol", "Or several causes at the same time", "Sometimes rapid progression, which needs urgent assessment", "Some causes partly reversible with treatment"],
 [{"myth": "All dementia is the same and untreatable.", "fact": "Some causes, like vitamin deficiency, thyroid problems, infections, and some alcohol-related damage, are treatable, which is why assessment matters."},
  {"myth": "HIV always leads to dementia.", "fact": "With effective antiretroviral treatment, severe HIV-related dementia is now rare, though milder changes can occur."},
  {"myth": "Alcohol-related brain damage can't improve.", "fact": "With abstinence, nutrition, and vitamin B1, many people improve substantially over months."}],
 {"plain": "These causes together account for a minority of dementia cases, with alcohol-related damage the most common of them in many countries. Prion disease is very rare.", "figure": "No single figure; alcohol-related brain damage estimated at around 10% of early-onset dementia in some settings; CJD about 1–2 cases per million per year", "source_ref": "src-dsm", "note": "Needs primary citations."},
 {"plain_summary": "Treatment depends on the cause. HIV is treated with HIV medicines. Alcohol damage is treated with stopping drinking, vitamin B1, and good food. Infections, thyroid, and vitamin problems are treated directly. MS, tumours, and prion disease need a nerve specialist. Rehab and support work the same way as for other dementias. If several causes combine, each is treated. For fast-moving conditions like CJD, comfort care is central.",
  "evidence_based_options": ["Treating the underlying cause where possible", "Thiamine and abstinence for alcohol-related damage", "Cognitive rehabilitation and support as for other dementias", "Palliative and family support for rapidly progressive disease"],
  "self_help_that_supports_care": ["Giving doctors a full history, including alcohol and medications", "Stopping alcohol and eating well where that's the cause", "Routines and memory aids", "Condition-specific support groups (HIV, alcohol recovery, brain injury, CJD)"],
  "guideline_refs": ["src-nice-ng97"]},
 "If thinking is getting worse and there's an illness, heavy drinking, or fast change, see a doctor for a full check. Some causes can be treated. Confusion that worsens over weeks is urgent.",
 "The common dementias (Alzheimer's, vascular, Lewy body, frontotemporal) have their own cards. Delirium is sudden and comes and goes. Being drunk or in withdrawal causes short-term confusion, not a lasting disorder, though repeated bouts can.",
 "When the cause is found, some of these conditions improve, and all of them can be supported. Assessment is worth it.",
 ["major-and-mild-neurocognitive-disorder", "alcohol-use-disorder", "delirium", "substance-medication-induced-mental-disorders", "mental-disorders-due-to-another-medical-condition"],
 ["dementia", "confabulation", "withdrawal", "carer-rights"],
 N_COMMS + ["reddit-r-stopdrinking"], ("Soft line illustration of a doctor and patient reviewing a checklist of tests together, a vitamin bottle and a water glass on the desk, bright clinic. Pastel amber and mint.", "A doctor and patient review a checklist of tests together in a bright clinic."),
 [DSM_N, NICE97], qs=["Find primary prevalence sources for each sub-cause."],
 subs=[{"title": "Sub-causes", "text": "Substance/medication-induced; due to HIV infection (B20 + F02.8x); due to prion disease (A81.9 + F02.8x); due to another medical condition; due to multiple etiologies; unspecified neurocognitive disorder (R41.9)."}]))

CARDS.append(N("delirium", "Delirium", "Sudden confusion with a medical cause", ["acute confusional state", "ICU delirium", "hospital-acquired confusion"], "F05 (due to another medical condition); others vary",
 "A sudden, fluctuating change in attention and awareness over hours or days, caused by illness, surgery, medication, or withdrawal.",
 "Delirium is a sudden, fluctuating disturbance in attention, awareness, and thinking, caused by something physical: infection, surgery, dehydration, pain, medication, alcohol or drug withdrawal, or organ problems. The person may be confused, drowsy or agitated, see things that aren't there, and be worse at night. It's very common in hospitals, especially in older people, and it's a medical emergency because it signals something is wrong. It's often missed and often preventable, and most people recover once the cause is treated.",
 ["Grandma went into hospital with a chest infection and came out thinking it was 1975. Three weeks later she was herself again.", "After the operation I saw spiders on the ceiling and was sure the nurses were poisoning me. I remember it vividly and I'm embarrassed, but they said it's common.", "The delirium was the first sign Dad had an infection. Nobody noticed until he started wandering."],
 ["Sudden onset over hours or days, fluctuating through the day", "Trouble focusing, following conversation, or staying alert", "Confusion about where they are, the time, or who people are", "Drowsy and withdrawn, or restless and agitated, or both", "Hallucinations, often visual; suspicious or fearful thoughts", "Worse in the evening and at night; disturbed sleep"],
 [{"myth": "Confusion in an older person is just dementia getting worse.", "fact": "A sudden change is delirium until proved otherwise, and delirium has a treatable cause. Dementia doesn't change over hours."},
  {"myth": "The person will remember nothing, so it doesn't matter.", "fact": "Many people remember delirium as terrifying. It also raises the risk of longer stays, falls, and lasting cognitive decline, so preventing it matters."},
  {"myth": "Sedatives are the treatment.", "fact": "The treatment is finding and fixing the cause. Sedatives are a last resort and can make delirium worse."}],
 {"plain": "Delirium affects around 1 in 7 older people in hospital at any time, and up to 1 in 4 develop it during an admission, with higher rates in intensive care and after surgery.", "figure": "Point prevalence 14.7% in adults 65+ across 45 UK hospitals; about 25% of older admitted patients develop delirium (meta-analysis)", "source_ref": "src-delirium-uk"},
 {"plain_summary": "Find and treat the cause: infection, dehydration, pain, constipation, medication, withdrawal, or organ failure. Alongside that, supportive care: a calm, well-lit room, familiar faces and objects, glasses and hearing aids, reorientation, good sleep, mobility, and avoiding unnecessary medications and ward moves. Medication for distress is used sparingly and with care. Prevention programmes in hospitals cut delirium by a third. Follow-up afterwards checks for lingering problems.",
  "evidence_based_options": ["Identifying and treating the underlying cause", "Multicomponent prevention and care: orientation, hydration, sleep, mobility, sensory aids", "Reviewing and reducing medications that cause delirium", "Careful, limited use of medication for severe distress; follow-up after recovery"],
  "self_help_that_supports_care": ["Family: being present, bringing glasses, hearing aids, photos, and familiar items", "Calmly reminding the person where they are and why", "Telling staff about any sudden change; you know the person best", "Afterwards: talking about what happened, which helps recovery"],
  "guideline_refs": ["src-nice-cg103"]},
 "If someone becomes suddenly confused, drowsy, agitated, or starts seeing things, especially an older person or someone who is ill or just had surgery, get medical help the same day. Tell staff if a person in hospital isn't their usual self.",
 "Dementia develops over months and years, not hours. Psychosis in a young, physically well person is unlikely to be delirium. Normal post-anaesthetic grogginess clears within hours.",
 "Most delirium resolves once the cause is treated. Families who recognize it early make all the difference.",
 ["major-and-mild-neurocognitive-disorder", "alzheimers-disease-neurocognitive-disorder", "alcohol-use-disorder", "sedative-hypnotic-anxiolytic-use-disorder", "substance-medication-induced-mental-disorders", "understanding-psychosis"],
 ["hallucination", "dementia", "sundowning", "withdrawal"],
 N_COMMS, ("Soft line illustration of a hospital room with a family member sitting beside an older patient, a wall clock, a window with daylight, family photos and glasses on the bedside table. Pastel amber and sky blue.", "A family member sits beside an older patient in a bright hospital room with photos and glasses on the bedside table."),
 [DSM_N, src("src-delirium-uk", "Delirium is prevalent in older hospital inpatients and associated with adverse outcomes: results of a prospective multi-centre study on World Delirium Awareness Day", "BMC Medicine (PMC6911703)", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6911703/", 2019, seen=True), src("src-nice-cg103", "Delirium: prevention, diagnosis and management in hospital and long-term care (CG103)", "NICE", "https://www.nice.org.uk/guidance/cg103", 2010, seen=True, note="Updated 2023.")],
 qs=["No delirium-specific peer community exists; family resources via dementia organizations."], sens="elevated", notes=["Medical emergency framing; crisis strip required."], clin=False,
 subs=[{"title": "Types by cause", "icd10cm_code": "F05; others vary", "text": "Substance intoxication delirium, substance withdrawal delirium, medication-induced delirium, delirium due to another medical condition, delirium due to multiple etiologies, other specified and unspecified delirium (R41.0)."}]))
